{"path": "/workspace/target/exp3.py", "content": "import json, re, unicodedata, itertools, sys
from pathlib import Path
from sklearn.feature_extraction.text import TfidfVectorizer

def norm(t):
    t = unicodedata.normalize("NFKC", str(t)).lower()
    return re.sub(r"\s+"," ",t).strip()
def nonorm(t):
    t = unicodedata.normalize("NFKC", str(t))
    return re.sub(r"\s+"," ",t).strip()

rows={}
for dom in ["cardiac","vascular","systemic"]:
    rows[dom]=[json.loads(l) for l in Path("data/cases",dom+"_cases.jsonl").read_text().splitlines() if l.strip()]
req=json.loads(Path("data/query_facets.json").read_text())
target = {"cardiac":[(11375,46),(33684,577)],"systemic":[(12117,29),(38723,548)],"vascular":[(12109,45),(36728,495)]}

def field(r, keys):
    parts=[]
    for k in keys:
        v=r.get(k,"")
        if isinstance(v,dict): v=json.dumps(v,sort_keys=True)
        parts.append(str(v))
    return " ".join(parts)

keysets=[("title","case_summary"),("title","case_summary","final_diagnosis"),("case_summary",),
         ("title","case_summary","journal"),("title","case_summary","final_diagnosis","journal"),
         ("title","case_summary","final_diagnosis","journal","domain_hits")]

token_patterns=[r"(?u)\b\w\w+\b", r"(?u)\b\w+\b", r"[A-Za-z0-9]+", r"\S+", r"[^\s]+", r"(?u)\b[\w-]+\b"]

for keys in keysets:
    for lower in [True, False]:
        prep = norm if lower else nonorm
        docsets={d:[prep(field(r,keys)) for r in rows[d]] for d in rows}
        qs={d:prep(req["facets"][d]) for d in rows}
        for tp in token_patterns:
            for ng in [(1,1),(1,2)]:
                for sa in ["unicode",None]:
                    res={}
                    for d in ["cardiac","systemic","vascular"]:
                        v=TfidfVectorizer(strip_accents=sa,analyzer="word",ngram_range=ng,min_df=1,token_pattern=tp,lowercase=lower)
                        M=v.fit_transform(docsets[d])
                        res[d]=(M.shape[1], v.transform([qs[d]]).nnz)
                    for vi in [0,1]:
                        if all(res[d]==tuple(target[d][vi]) for d in res):
                            print("MATCH",vi,keys,lower,tp,ng,sa,res); sys.stdout.flush()
                        elif res["cardiac"]==tuple(target["cardiac"][vi]) or res["systemic"]==tuple(target["systemic"][vi]):
                            print("partial",vi,keys,lower,tp,ng,sa,res); sys.stdout.flush()
                    print("  ",keys,lower,tp,ng,sa,res); sys.stdout.flush()
