{"path": "/workspace/target/src/artifact_loader.py", "content": """"Case-record loading for the deployed candidate.

Population authority is the release manifest (active entries only); identity
authority is the release registry joined on the stable ``record_key``.
"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not path.exists():
        return rows
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(row, dict):
            rows.append(row)
    return rows


def load_registry(artifact_root: Path) -> dict[str, dict[str, Any]]:
    """Canonical identity: record_key -> {pmcid, domain}."""
    manifest_path = artifact_root / "source_manifest.json"
    registry_name = "release_registry.jsonl"
    if manifest_path.exists():
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            registry_name = str(manifest.get("identity_registry") or registry_name)
        except json.JSONDecodeError:
            pass
    registry: dict[str, dict[str, Any]] = {}
    for row in _read_jsonl(artifact_root / registry_name):
        key = str(row.get("record_key", "")).strip()
        if not key:
            continue
        registry[key] = {
            "pmcid": str(row.get("pmcid", "")).strip(),
            "domain": str(row.get("domain", "")).strip(),
        }
    return registry


def load_manifest(artifact_root: Path) -> dict[str, Any]:
    manifest_path = artifact_root / "source_manifest.json"
    if not manifest_path.exists():
        return {}
    try:
        return json.loads(manifest_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}


def load_cases(artifact_root: Path) -> list[dict[str, Any]]:
    """Release population: active manifest files, registry-joined, deduplicated."""
    artifact_root = Path(artifact_root)
    manifest = load_manifest(artifact_root)
    registry = load_registry(artifact_root)

    entries = manifest.get("files") or []
    active_paths: list[Path] = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        if not entry.get("active", False):
            continue
        rel = str(entry.get("path", "")).strip()
        if not rel:
            continue
        active_paths.append(artifact_root / rel)

    if not active_paths:  # defensive fallback only
        active_paths = sorted((artifact_root / "cases").glob("*.jsonl"))

    seen: set[str] = set()
    rows: list[dict[str, Any]] = []
    for path in active_paths:
        for row in _read_jsonl(path):
            key = str(row.get("record_key", "")).strip()
            if not key:
                continue
            canonical = registry.get(key)
            if canonical is None:
                # not release authority
                continue
            if key in seen:
                continue
            seen.add(key)
            record = dict(row)
            record["record_key"] = key
            record["pmcid"] = canonical["pmcid"]
            record["source"] = canonical["domain"]
            rows.append(record)

    rows.sort(key=lambda r: (str(r["source"]), str(r["pmcid"]), str(r["record_key"])))
    return rows


def load_request(path: Path) -> dict[str, Any]:
    return json.loads(Path(path).read_text(encoding="utf-8"))
"}

{"path": "/workspace/target/src/text_views.py", "content": """"Text normalization and eligible-document assembly for the deployed candidate.

Serving boundary is pre-outcome: only pre-outcome narrative fields (title and
case summary) are eligible retrieval text.  Post-adjudication fields
(``final_diagnosis``, ``domain_hits``) and display metadata (``journal``,
``pmcid``) are excluded from the lexical index.
"""
from __future__ import annotations

import re
import unicodedata
from typing import Any

ELIGIBLE_FIELDS = ("title", "case_summary")


def normalize(text: str) -> str:
    text = unicodedata.normalize("NFKC", str(text)).lower()
    return re.sub(r"\s+", " ", text).strip()


def document_text(row: dict[str, Any]) -> str:
    return normalize(" ".join(str(row.get(field, "")) for field in ELIGIBLE_FIELDS))


def request_text(value: Any) -> str:
    return normalize(value)
"}

