def ranks(scores, tb):
    order=np.lexsort((np.array(tb,dtype=object).astype(str), -np.asarray(scores)))
    r=np.empty(len(order),dtype=int)
    for p,i in enumerate(order,1): r[i]=p
    return r

doms={}
for dom in ["cardiac","systemic","vascular"]:
