def request_phase_inputs(request: dict[str, Any], facets: dict[str, Any]) -> int:
    """UTF-8 byte total of the normalized request evidence (query id + facets)."""
    parts = [normalize(str(request.get("query_id", "")))]
    for key in sorted(facets):
        parts.append(normalize(str(facets[key])))
    return sum(len(p.encode("utf-8")) for p in parts)


def family_cycle(request: dict[str, Any], facets: dict[str, Any], top_k: int,
                 families: list[str] | None = None) -> list[str]:
    """Request-phased balanced cyclic emission with alternating direction.

    Phase (start family) = normalized-request byte total modulo the active
    cause-family count; direction alternates with the parity of the request
    size (odd -> forward, even -> backward).
    """
    fams = list(families) if families else list(FAMILIES)
    fams = sorted(fams)
    n = len(fams)
    if n == 0:
        return []
    total_bytes = request_phase_inputs(request, facets)
    phase = total_bytes % n
    step = 1 if int(top_k) % 2 == 1 else -1
    return [fams[(phase + i * step) % n] for i in range(n)]


